INSERT INTO squad_entries VALUES(14,1,59,'알리송(신규)','WM','OWNED','001331015X001370003500013',6.879999999999999894,'r6','확장 22경기 평균 6.88 (그레미우+빌라)','wm_widemid','Build-Up',0.8329999999999999627,'appearances measured','OWNED / [2026-08-14] grid_club을 ''브라질 클럽''에서 **그레미우**로 구체화했다. ⚠️ 검색 시 **동명이인 오염**에 주의 — 크루제이루 유스 출신 Alysson(1997년생 CB)이 별도로 존재한다. 우리 선수는 2006-05-05생(아푸카라나), 2018년 12세에 그레미우 입단, 2024-07-07 세리에A 데뷔. 크루제이루는 빌라 스카우트가 그를 처음 확인한 **상대 팀**이다.',53,'그레미우 (Grêmio, Brasileirão)','⚠️ 빌라 공식전 0경기 — 그리드 전량이 브라질 무대(Brasileirao 20 · Sudamericana 2, 2025-07~12). 리그 수준 보정 없음.',NULL);
