INSERT INTO squad_entries VALUES(59,1,28,'일링주니어','WM','OWNED','001361017X001271013800023',6.419999999999999929,'full2526','RM 9경기 평균 6.42 (measured:season:full2526)','wm_winger','Balanced',0.7800000000000000266,NULL,NULL,79,'임대처(Championship·Serie A)','⚠️ 빌라 공식전 0경기 — 그리드 전량이 임대 시절(Championship 14 · Serie A 1, 2025-09~2026-02). ⚠️ 챔피언십은 PL과 리그 수준이 다르다.',NULL);
INSERT INTO squad_entries VALUES(60,1,78,'루헤리','FB','CONFIRMED','310009200081000X300052100',6.719999999999999752,'full2526','LB 45경기 평균 6.72 (measured:season:full2526)','fb_att_wb','Support',0.931000000000000049,NULL,unistr('\u000a⭐ **[2026-08-19] 빌라 공식 발표로 CONFIRMED 확정.** 이 행은 발표 이전에 생성돼 있었고, 오늘 `transfer_targets`(id=141)를\u000aHIGH → CONFIRMED로 갱신해 정합을 맞췄다. ⚠️ 그리드는 **아틀레티코 45경기** 실측이며 빌라 공식전 0경기다(불변규칙 7).\u000a**[2026-08-19] 뎁스차트 위치 이동 — sort_order 80 → 23**(사용자 판단: 「보유 그룹 안, 기존 선발 뒤」).\u000a종전 80은 **FB 후보 맨 끝**이라 시즌 임대로 나가는 네델코비치(73)보다도 뒤였다 — 공식 영입 후의 자리가 아니다.\u000a23은 마첸(20)·캐시(21)·보가르드(22) 뒤, 네델코비치(73) 앞이다. ⇒ 히트맵·XI의 **기본 선발은 마첸·캐시 그대로 유지**되고\u000a루헤리는 드롭다운 4번째로 올라온다. ⚠️ 다른 CONFIRMED 영입(시세 8·만잠비 11·고메스 12·가르나초 15)은 그룹 **선두**에 놓였으나,\u000a이 건은 「영입했지만 아직 주전으로 확정하지 않았다」는 판단이라 관례와 의도적으로 다르다.'),23,'Atlético Madrid','⚠️ 빌라 공식전 0경기 — 그리드 전량이 아틀레티코 마드리드 시절(25/26 45분+ 45경기)이다. 적합값은 "아틀레티코에서 하던 일"의 적합이며 에메리 전술에서 같은 위치를 쓴다는 근거가 아니다(obs#157·#158). ⭐ 같은 선수가 팀을 옮기자 좌우 위치가 17~18단위 움직인 사례가 둘 있다(베일리·게상, obs#158).','LB');
INSERT INTO squad_entries VALUES(61,3,85,'아라우호','CB','CONFIRMED','001000012101594015X400232',7.150000000000000355,'full2526','RCB 22경기 평균 7.15 (measured:season:full2526)','cb_bpd','Aggressive',0.9080000000000000293,NULL,NULL,10,'Barcelona','⚠️ 리버풀 공식전 0경기 — 그리드 전량이 **바르셀로나 시절**(25/26 45분+ 22경기)이다. 적합값은 "바르셀로나에서 하던 일"의 적합이며 이라올라 전술에서 같은 위치를 쓴다는 근거가 아니다(obs#157·#158). ⭐ 같은 선수가 팀을 옮기자 좌우 위치가 17~18단위 움직인 사례가 둘 있다(베일리·게상, obs#158). ⚠️ 이라올라 체제는 공식전 0경기다(첫 경기 8/23 뉴캐슬 원정).',NULL);
INSERT INTO squad_entries VALUES(63,2,80,'차바리아','FB','CONFIRMED','510009210093100X510053100',6.799999999999999823,'full2526','LB 39경기 평균 6.80 (measured:season:full2526)','fb_att_wb','Support',0.8900000000000000133,'SofaScore 25/26 전수 55경기 중 45분+ 39경기 ; 구단 공식 https://www.chelseafc.com/en/news/article/pep-chavarria-signs-for-chelsea','39/39 전 경기 좌측 우세(좌2컬럼 0.93 · 우2 0.00)라 좌우 혼입 없음.',5,'Rayo Vallecano (25/26)','⚠️ 첼시 공식전 0경기 — 그리드 전량이 **라요 바예카노 시절**(25/26 45분+ 39경기)이다. 적합값은 "라요에서 하던 일"의 적합이며 알론소 전술에서 같은 위치를 쓴다는 근거가 아니다(obs#157·#158). ⭐ 같은 선수가 팀을 옮기자 좌우 위치가 17~18단위 움직인 사례가 둘 있다(베일리·게상, obs#158). ⚠️ 알론소 체제는 공식전 0경기다(첫 경기 8/24 풀럼). ⚠️ 포지션은 **하토의 백업·경쟁**이며 주전 결손 보강이 아니다.',NULL);
INSERT INTO squad_entries VALUES(64,3,88,'무뇨스','WM','CONFIRMED','54123X5222422114211111100',7.030000000000000248,'full2526','좌측 23경기 평균 7.03 (measured:season:full2526)','wm_wideplm','Attack',0.7289999999999999814,'SofaScore player 1145642, 25/26 오사수나 클럽경기(라리가+코파) 45분+·히트포인트 15+ 34경기 중 좌측 23경기(1898분) 균등가중 ; 구단 공식 https://www.liverpoolfc.com/news/liverpool-agree-deal-sign-spain-forward-victor-munoz (2026-06-18)','⭐ **양 측면 자원이라 좌우를 분리했다**(obs#156 규약). 34경기 혼합으로 재면 LM .615로 급락하는데, 이는 좌 23·우 11이 섞여 그리드가 중앙으로 뭉개지기 때문이다. 좌우 분리 후: **좌측 23경기 LM wm_wideplm/Attack .729** / 우측 11경기 RM wm_winger/Balanced .772. 주 표본(좌측, 2배 표본)을 행 값으로 채택했다.',11,'Osasuna (25/26)','⚠️ 리버풀 공식전 0경기 — 그리드 전량이 **오사수나 시절**(25/26 45분+ 34경기 중 좌측 23경기)이다. 적합값은 "오사수나에서 하던 일"의 적합이며 이라올라 전술에서 같은 위치를 쓴다는 근거가 아니다(obs#157·#158). ⭐⭐ **우측으로 쓰면 값이 달라진다** — 우측 11경기만 재면 **RM wm_winger/Balanced .772**로 좌측(.729)보다 높다. 살라 이탈로 리버풀의 결손 칸이 우측인 점을 감안하면 이 행 하나로 판단하지 말 것. ⚠️ 이라올라 체제는 공식전 0경기다(첫 경기 8/23 뉴캐슬 원정). ⚠️ 표본은 라리가 중위권 팀의 것이다 — 리그·팀 수준 보정 없음.',NULL);
INSERT INTO squad_entries VALUES(65,3,89,'자케','CB','CONFIRMED','001001012013752147X311562',7.080000000000000071,'full2526','RCB 14경기 평균 7.08 (measured:season:full2526)','cb_bpd','Aggressive',0.9030000000000000248,'SofaScore player 1445625, 25/26 렌 클럽경기(리그1+쿠프드프랑스) 45분+·히트포인트 15+ 21경기 중 우측 14경기(1239분) 균등가중 ; 구단 공식 https://www.liverpoolfc.com/news/liverpool-complete-signing-jeremy-jacquet (2026-07-01)','⭐ **좌우 분리 적용**(obs#156). 21경기 혼합 RCB .838 → 우측 14경기만 **RCB cb_bpd/Aggressive .903**. 좌측 7경기만 재면 LCB .850이라 **양쪽 다 가능하나 우측이 주 표본이자 argmax**다. 표본이 렌 소속 21경기로 충분(1853분).',12,'Rennes (25/26)','⚠️ 리버풀 공식전 0경기 — 그리드 전량이 **렌 시절**(25/26 45분+ 21경기 중 우측 14경기)이다. 적합값은 "렌에서 하던 일"의 적합이며 이라올라 전술 근거가 아니다(obs#157·#158). ⭐⭐ **아라우호와 같은 칸을 다툰다** — 아라우호 RCB **.908** vs 자케 RCB **.903**로 Δ.005는 EA 노이즈 구간(.02~.05, obs#91) **훨씬 안쪽**이라 적합값으로는 두 사람을 가를 수 없다. 자케는 좌측 7경기 LCB .850도 있어 **좌측 이동 여지가 아라우호(LCB .271로 붕괴)보다 크다** — 이 비대칭이 실제 인선의 결정 변수일 수 있다. ⚠️ 이라올라 체제는 공식전 0경기다. ⚠️ 표본은 리그1의 것 — 리그 수준 보정 없음. ⚠️ 25/26 시즌 말 어깨 부상으로 결장한 이력이 있다.',NULL);
INSERT INTO squad_entries VALUES(66,1,30,'헤밍스','WM','OWNED','66111X4430X41009403004000',6.200000000000000177,'event:16260286','슈퍼컵 PSG전 90분 평점 6.2','wm_widemid','Support',0.7880000000000000337,'SofaScore event 16260286 — LAM 90분·히트포인트 51·평균위치 (58.11,73.31)','HIGH 원천 데이터 / MEDIUM 대표 역할 — 단일 공식전 표본',81,'Aston Villa (2026-27)','⚠️ 공식전 1경기. LM/LAM 대표 역할 확정 전 추가 표본 필요.',NULL);
INSERT INTO squad_entries VALUES(67,1,55,'만잠비','WM','CONFIRMED','35345X9578542261322300020',7.200000000000000177,'national','스위스 대표팀 12경기 평균 7.2','wm_wideplm','Attack',0.6520000000000000239,'transfer_targets id=122 LM 승격 (현재 스쿼드 정합성 수리)','CONFIRMED 영입은 squad_entries 승격이 규칙. LM 적합은 대표팀 전진 배치 표본.',16,'SC Freiburg + 스위스 대표팀','⚠️ 빌라 공식전 0경기 — 대표팀 표본은 포지션 혼입(CAM 선발 2경기뿐)이고 좌우 평균 산물이다(obs#156).',NULL);
INSERT INTO squad_entries VALUES(68,1,132,'스즈키','GK','CONFIRMED','0000000000000000010001X20',7.049999999999999823,'full2526','GK 29경기 평균 7.05 (파르마·일본대표 실측 · measured:season:full2526)','gk_goalkeeper','Defend',0.974999999999999978,'transfer_targets id=149 GK 승격 (2026-08-17) · prescriptions measured:season:full2526 · obs#220·#222·#223·#234',unistr('CONFIRMED 영입은 squad_entries 승격이 규칙. ⚠️ **양 구단 공식 발표는 여전히 0건이다**(2026-08-18 메인 세션이 avfc.co.uk 뉴스·parmacalcio1913.com/news 직접 파싱해 확인 — 빌라 최신은 FPL 프리뷰·글라드바흐전·일링 볼턴 임대, 파르마 최신은 로메로 영입·온드레이카 임대). ⇒ **DB에 못 박은 CONFIRMED 트리거(`avfc.co.uk 공식 발표`)는 미충족 상태이고, 이 승격은 사용자 지시에 따른 것이다.** 근거 상한: **메디컬 실시 확인**(Romano 1티어 08-17 07:21 UTC) + **개인 조건 5년 계약 합의**(Ornstein 1티어) + **£29.9m/€30m+€5m 구단 간 합의**(Sky UK 1티어 08-16) + **Moretto(2티어) ''완료''**. ⛔ **''here we go''는 이 건에 붙지 않았다** — 일부 매체 헤드라인의 HWG는 태그 전용(轉用)이다(obs#234·transfer-watch 기록). ⚠️ obs#233(오늘 다른 세션)이 **''신호 하나로 등급을 올렸다가 24시간 만에 뒤집힌''** 마르티네스 사례를 남겼다 — 다만 스즈키는 **메디컬 이후** 단계이고 PSG 결렬은 **메디컬 직전**이었다는 점에서 국면이 다르다. ⇒ **공식 발표가 확인되면 이 캐비앗을 해제하고, 반대로 결렬되면 이 행들을 되돌려야 한다.**\u000a⭐⭐ **[2026-08-19] 캐비앗 해제 — 빌라 공식 발표 확인.** avfc.co.uk `/news/2026/august/19/signing-villa-confirm-suzuki-signing/`\u000a(완전이적 명시). 위에 적힌 「CONFIRMED 트리거 미충족 · 사용자 지시에 따른 승격 · 결렬 시 되돌려야 한다」는 **더 이상 적용되지 않는다.**\u000a⚠️ 단 grid_caveat(파르마 딥블록 표본 · GK 커널 미변별)는 실측 한계이므로 **그대로 유효**하다.'),11,'Parma','⚠️ 빌라 공식전 0경기 — 그리드는 파르마 22경기 + 일본대표 7경기(45분+ · 히트맵 15pt+, 2602분)에서 나왔다. ⛔ GK는 커널 적합이 변별하지 못한다(obs#220, 측정 GK 5명 상호 코사인 ≥0.986) — 변별은 평균 위치다(tool_y 10.06으로 마르티네스 11.16보다 1.10 깊다). ⚠️ 파르마는 잔류권 딥블록이라 빌라의 높은 라인에서 같은 값이 재현된다는 근거가 아니다(불변규칙 7).',NULL);
